import mediaManifest from './groups/cherrybullet/host-media.json' with {type:'json'};
export {mediaManifest};
const facts=new Map(mediaManifest.images.map(row=>[row.path,row]));
/** This phase admits local/same-origin image reads only. All production APIs stay inactive. */
export function guardImageResolver(resolveImage,origin){
  if(typeof resolveImage!=='function')throw new TypeError('Cherry Bullet requires an explicitly injected read-only resolver');
  return async(descriptor,context)=>{
    const fact=facts.get(descriptor?.canonicalPath);
    if(!fact||descriptor.groupId!==mediaManifest.groupId||descriptor.slug!=='cherrybullet'||descriptor.sha256!==fact.sha256||descriptor.bytes!==fact.bytes||descriptor.naturalWidth!==fact.naturalWidth||descriptor.naturalHeight!==fact.naturalHeight||descriptor.qualityLevel!==fact.declaredQualityLevel)throw new Error('Cherry Bullet image descriptor rejected');
    const result=await resolveImage(descriptor,context);
    if(context.signal.aborted)return result;
    let url;try{url=new URL(result?.url,origin);}catch{throw new Error('Cherry Bullet image address rejected');}
    let path;try{path=decodeURIComponent(url.pathname);}catch{throw new Error('Cherry Bullet image path rejected');}
    const localPath='/_sol15-originals/cherrybullet/'+descriptor.sha256+'/'+descriptor.canonicalPath.split('/').at(-1);
    if(url.origin!==origin||url.username||url.password||url.hash||url.search||path!==localPath||url.pathname!==localPath||!['http:','https:'].includes(url.protocol))throw new Error('Cherry Bullet image address is outside the local-only, inactive-production boundary');
    return result;
  };
}
/** Explicit test-only same-origin map; never a production storage API. */
export function createLocalImageResolver(entries,origin){
  if(!Array.isArray(entries)||entries.length!==facts.size)throw new Error('Expected all '+facts.size+' Cherry Bullet local addresses');
  const mapped=new Map(),urls=new Map();
  for(const entry of entries){
    const fact=facts.get(entry?.canonicalPath);
    if(!fact||mapped.has(fact.path)||entry.groupId!==mediaManifest.groupId||entry.slug!=='cherrybullet'||entry.sha256!==fact.sha256||entry.bytes!==fact.bytes||entry.naturalWidth!==fact.naturalWidth||entry.naturalHeight!==fact.naturalHeight||entry.qualityLevel!==fact.declaredQualityLevel||typeof entry.url!=='string')throw new Error('Local image identity rejected');
    if(urls.has(entry.url)&&urls.get(entry.url)!==fact.sha256)throw new Error('Local image address reused for different bytes');
    urls.set(entry.url,fact.sha256);mapped.set(fact.path,Object.freeze({...entry}));
  }
  return guardImageResolver((descriptor,{signal})=>{if(signal.aborted)throw new DOMException('Aborted','AbortError');return mapped.get(descriptor.canonicalPath);},origin);
}

import {artist} from './groups/cherrybullet/index.js';
import {entityKey} from './shared/helpers.js';
import {describeHostEntity} from './shared/host-contract.js';
import {parseReviewRoute,productionReturn} from '../vcha-runtime/bridge.mjs';
import stageBindings from './cherrybullet-stage-bindings.json' with {type:'json'};

export const REVIEW_PATH='/design-review/sol15/cherry-bullet';
export const group=Object.freeze({slug:'cherrybullet',groupId:artist.id,
  members:artist.members.map(row=>({key:entityKey(row),memberId:row.id})),
  media:artist.works.filter(row=>['mv','stage'].includes(row.type)).map(row=>({key:entityKey(row),kind:row.type})),
  releases:artist.works.filter(row=>row.type==='release').map(row=>({key:entityKey(row)}))});
export const urlNow=win=>win.location.pathname+win.location.search+win.location.hash;
export const reviewTarget=hash=>parseReviewRoute(group,hash)?REVIEW_PATH+hash:null;
export function readReviewUrl(value){
  if(typeof value!=='string'||/[\\\u0000-\u0020]/.test(value))return null;
  try{const url=new URL(value,'https://review.invalid');return url.origin==='https://review.invalid'&&url.pathname===REVIEW_PATH&&!url.search?parseReviewRoute(group,url.hash||'#/cherrybullet'):null;}catch{return null;}
}
export function catalogBelongs(value){
