    Array.isArray(value.groups)&&value.groups.filter(row=>row?.id===artist.id).length===1&&Array.isArray(value.members)&&Array.isArray(value.works));
}
/** Discard private display-v1 fields immediately. This is never a save payload. */
export function nativeCatalogProjection(value){
  if(!catalogBelongs(value))return null;
  return structuredClone({scope:{type:'artist',groupId:artist.id},groups:value.groups.map(row=>({id:row.id})),
    members:value.members.map(row=>({id:row.id,groupIds:row.groupIds,formerGroupIds:row.formerGroupIds})),
    works:value.works.map(row=>({id:row.id,groupIds:row.groupIds,url:row.url,videoType:row.videoType,version:row.version,placeholder:Boolean(row.placeholder),
      stage:row.stage?{videoId:row.stage.videoId,url:row.stage.url,kind:row.stage.kind,clip:row.stage.clip,
        sourceClass:row.stage.sourceClass,platform:row.stage.platform,completeness:row.stage.completeness,scorePolicy:row.stage.scorePolicy,
        scoreBinding:row.stage.scoreBinding?{videoId:row.stage.scoreBinding.videoId,sourceKey:row.stage.scoreBinding.sourceKey,initialScore:row.stage.scoreBinding.initialScore===null?null:undefined,initializedAt:row.stage.scoreBinding.initializedAt}:null}:null}))});
}
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const belongs=row=>Array.isArray(row?.groupIds)&&row.groupIds.includes(artist.id);
