/** Exact current public tuple + live host IDs; a candidate key alone grants nothing. */
export function resolveNative(identity,route,catalog,production){
  if(!catalogBelongs(catalog)||!identity||!['member','work'].includes(route?.page))return null;
  let expected;try{expected=describeHostEntity({artist,kind:route.page,key:route.key,route}).identity;}catch{return null;}
  if(!same(identity,expected))return null;
  if(identity.entityType==='member'){
    const rows=catalog.members.filter(row=>row?.id===identity.memberId);
    return rows.length===1&&(belongs(rows[0])||Array.isArray(rows[0].formerGroupIds)&&rows[0].formerGroupIds.includes(artist.id))?{kind:'member',memberId:rows[0].id,identity:expected}:null;
  }
  if(!['mv','stage'].includes(identity.entityType)||!/^rec[A-Za-z0-9]+$/.test(identity.workId??'')||!identity.videoId)return null;
  if(identity.entityType==='stage'&&identity.parentWorkIds.length!==1)return null;
  const rows=catalog.works.filter(row=>row?.id===identity.workId);
  if(rows.length!==1||rows[0].placeholder||!belongs(rows[0]))return null;
  const work=rows[0],version=identity.entityType==='mv'?identity.version:identity.selectedParentVersion;
  if(work.videoType!==identity.videoType||work.version!==version)return null;
  if(identity.entityType==='mv'){
    if(identity.slotType!=='MV'||work.url!==identity.videoSourceUrl||videoId(work.url)!==identity.videoId)return null;
    if(catalog.works.filter(row=>!row.placeholder&&belongs(row)&&videoId(row.url)===identity.videoId).length!==1)return null;
    return {kind:'mv',workId:work.id,videoId:identity.videoId,sourceKey:null,clip:null,identity:expected};
  }
  const stage=work.stage,proof=stageBindings[work.id];
  if(identity.slotType!=='STAGE'||!stage||!proof||stage.videoId!==identity.videoId||proof.videoId!==identity.videoId||
    stage.url!==identity.videoSourceUrl||stage.url!==proof.url||stage.kind!==proof.kind||stage.clip!=null||proof.clip!=null||
    production.stageSourceKey(stage)!==identity.videoId||!production.stageHasValidBinding(stage))return null;
  const aliases=catalog.works.filter(row=>!row.placeholder&&belongs(row)&&production.stageSourceKey(row.stage)===identity.videoId);
  if(aliases.length!==1)return null;
  return {kind:'stage',workId:work.id,videoId:stage.videoId,sourceKey:production.stageSourceKey(stage),clip:null,identity:expected};
}
export function nativeHref({identity,route,catalog,production,mountedUrl,currentUrl,mayLeave}){
  if(!mayLeave||mountedUrl!==currentUrl||!readReviewUrl(currentUrl))return null;
  const entity=resolveNative(identity,route,catalog,production);if(!entity)return null;
  const artistReturn=productionReturn(group,route,production);if(!artistReturn)return null;
  return production.routeUrl(entity.kind==='member'
    ?{nav:'members',member:entity.memberId,work:null,video:'mv',artistReturn}
    :{nav:'works',member:null,work:entity.workId,video:entity.kind,artistReturn});
}

