  const tree=node=>{let top=node;while(top.parentNode)top=top.parentNode;return top.nodeType===11?top:doc;};
  const focus=node=>{for(const shadow of shadows)shadow.activeElement=null;let active=node,current=tree(node);while(current.nodeType===11){current.activeElement=active;active=current.host;current=tree(active);}doc.activeElement=active;node.focused++;};
  const create=doc.createElement.bind(doc);doc.createElement=tag=>{const node=create(tag);node.nodeType=1;node.getRootNode=()=>tree(node);node.getBoundingClientRect=()=>({left:10,top:10,width:640,height:tag==='h2'?24:400});node.focus=()=>focus(node);return node;};
  Object.assign(win,{innerWidth:1440,innerHeight:900,getComputedStyle:()=>({overflow:'visible'}),requestAnimationFrame(fn){const id=++serial;frames.set(id,fn);return id;},cancelAnimationFrame:id=>frames.delete(id)});
  const shadowFor=(host,closed=false)=>{const shadow=doc.createElement('shadow-root');shadow.nodeType=11;shadow.host=host;shadow.activeElement=null;if(!closed)host.shadowRoot=shadow;shadows.push(shadow);return shadow;};
