 test(slug+': the rendered single timeline is oldest-first, undated histories remain distinct',async()=>{
   const {api}=await start('#/'+slug+'/timeline');
   const views=publicTimeline(artist),dated=views.filter(v=>v.mainDate).map(v=>v.mainDate);
   assert.deepEqual(dated,[...dated].sort());assert.deepEqual(api.root.querySelectorAll('[data-event-id]').map(n=>n.getAttribute('data-event-id')),views.map(v=>v.id));
   assert.equal(api.root.querySelectorAll('[data-timeline]').length,1);api.destroy();
 });
 test(slug+': every exact release event opens its own release, then returns to the event context',async()=>{
   const {h,api}=await start('#/'+slug+'/timeline');
   for(const row of links){
     assert(api.navigate('#/'+slug+'/timeline'));await tick();
     const item=api.root.querySelector('[data-event-id="'+row.eventId+'"]');assert(item);
     const target=item.querySelector('[data-release-relation="'+row.releaseEntityKey+'"]');assert(target,row.eventId);
     const parsed=parseRoute(target.getAttribute('href'));assert.equal(parsed.key,row.releaseEntityKey);assert.equal(parseRoute(returnDestination(parsed)).query.get('event'),row.eventId);
     h.click(target);await tick();assert(api.root.querySelector('[data-work-key="'+row.releaseEntityKey+'"]'));
     const back=api.root.querySelectorAll('a[href]').find(a=>parseRoute(a.getAttribute('href')).page==='timeline'&&!a.hasAttribute('data-release-timeline'));
     // The explicit back control is decorated to its originating timeline.
