 });
 test(slug+': release/video/parent-release are exact bidirectional links, including stages, with no first-parent or title join',async()=>{
   const {h,api}=await start('#/'+slug+'/works');
   for(const row of links){
     const release=releaseForEvent(artist,row.eventId);assert(release);assert.equal(entityKey(release),row.releaseEntityKey);
     const videos=releaseRelations(artist,release);
     assert.deepEqual(videos.filter(w=>w.type==='mv').map(w=>w.id),row.workIds,'Only supplied exact work IDs join');
     for(const video of videos){
       assert(releaseRelations(artist,video).some(r=>entityKey(r)===entityKey(release)));
       assert(api.navigate('#/'+slug+'/work/'+encodeURIComponent(entityKey(release))));await tick();
       const a=api.root.querySelector('[data-release-relation="'+entityKey(video)+'"]');assert(a);h.click(a);await tick();
       assert.equal(parseRoute(h.win.location.hash).key,entityKey(video));assert(api.root.querySelector('[data-work-key="'+entityKey(video)+'"]'));
       const parent=api.root.querySelector('[data-release-relation="'+entityKey(release)+'"]');assert(parent);h.click(parent);await tick();assert.equal(parseRoute(h.win.location.hash).key,entityKey(release));
     }
   }
   const source=artist.works.find(w=>w.type==='mv');
