 test(slug+': original release singles remain separate and all native release IDs remain absent; dates are separate facts',()=>{
   for(const release of artist.works.filter(w=>w.type==='release')){assert.equal(release.id,null);assert.equal(release.projectReleaseId,null);assert(release.sources.length>0);}
   assert.equal(artist.members.length,slug==='cherrybullet'?10:7);
 });
 test(slug+': related-detail return preserves timeline and filtered list state without expanding on parent cycles',()=>{
   const row=links.find(r=>r.workIds.length),release=row.releaseEntityKey;
   let route={slug,page:'timeline',key:null,query:new URLSearchParams('q=preserved')};
   const toRelease=detailNavigationHref(route,{slug,page:'work',key:release,query:new URLSearchParams({event:row.eventId})});
   const baseline=parseRoute(toRelease);
   for(let i=0;i<20;i++){
     const video=parseRoute(detailNavigationHref(baseline,{slug,page:'work',key:row.workIds[0],query:new URLSearchParams()}));
